param(
    [switch]$Commit,
    [switch]$AllowOtherBranch
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$ExpectedBranch = 'agent/lobby-mvp-integration'
$InstallerVersion = 2
$PayloadSha256 = 'b60ce4f030fe9d16dbbfca87f088daca99cc1eb3a80f8ceda7ad953a28268518'

function Fail([string]$Message) {
    Write-Host ''
    Write-Host ('ERRO: ' + $Message) -ForegroundColor Red
    exit 1
}

function Run-Git {
    param([string[]]$Args, [string]$WorkingDirectory)
    $old = Get-Location
    try {
        if ($WorkingDirectory) { Set-Location $WorkingDirectory }
        & git @Args
        if ($LASTEXITCODE -ne 0) {
            throw "git $($Args -join ' ') falhou com codigo $LASTEXITCODE"
        }
    } finally {
        Set-Location $old
    }
}

function Test-GitApply {
    param([string]$Repo, [string]$Patch)
    $old = Get-Location
    try {
        Set-Location $Repo
        & git apply --check --whitespace=nowarn $Patch 2>$null
        return ($LASTEXITCODE -eq 0)
    } finally {
        Set-Location $old
    }
}

function Apply-Patch {
    param([string]$Repo, [string]$Patch, [string]$Label)
    if (-not (Test-GitApply -Repo $Repo -Patch $Patch)) {
        throw "$Label nao e compativel com o estado atual."
    }
    $old = Get-Location
    try {
        Set-Location $Repo
        & git apply --whitespace=nowarn $Patch
        if ($LASTEXITCODE -ne 0) { throw "$Label falhou durante git apply." }
    } finally {
        Set-Location $old
    }
}

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' Infinity Islands - Instalador Tasks 01 -> 20  [V2]' -ForegroundColor Cyan
Write-Host ' Task 14 corrigida para o IslandMarkerService REAL' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ''

if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    Fail 'Git nao foi encontrado no PATH.'
}

$RepoRoot = (& git rev-parse --show-toplevel 2>$null).Trim()
if ([string]::IsNullOrWhiteSpace($RepoRoot)) {
    Fail 'Execute este arquivo dentro da pasta do repositorio Infinity Islands.'
}

$CurrentBranch = (& git -C $RepoRoot branch --show-current).Trim()
if (-not $AllowOtherBranch -and $CurrentBranch -ne $ExpectedBranch) {
    Fail "Branch atual '$CurrentBranch'. Esperado '$ExpectedBranch'."
}

$Dirty = (& git -C $RepoRoot status --porcelain)
if ($Dirty) {
    Write-Host 'Alteracoes nao commitadas detectadas:' -ForegroundColor Yellow
    $Dirty | ForEach-Object { Write-Host ('  ' + $_) -ForegroundColor Yellow }
    Fail 'Faca commit ou stash antes de instalar.'
}

$StartHead = (& git -C $RepoRoot rev-parse HEAD).Trim()
$Timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$BackupBranch = "backup/mobile-dungeon-tasks01-20-v2-$Timestamp"
$TempBase = Join-Path ([IO.Path]::GetTempPath()) ("InfinityIslandsInstallerV2-" + [Guid]::NewGuid().ToString('N'))
$PayloadDir = Join-Path $TempBase 'payload'
$TempWorktree = Join-Path $TempBase 'preflight-worktree'
$PayloadZip = Join-Path $TempBase 'payload.zip'
New-Item -ItemType Directory -Path $PayloadDir -Force | Out-Null

