    'UlNUX1JFV0FSRF9DT01QTEVURS5naXQucGF0Y2hQSwECFAMUAAAACADJtQddCGzhOqoAAACvAQAAOgAAAAAAAAAAAAAApIFAegEAcGF0Y2hlcy8yMF8zNF81'
    'M19SVU5USU1FX0dFTkVSQVRPUl9DT05URU5UX1BIQVNFLmdpdC5wYXRjaFBLAQIUAxQAAAAIAMm1B10iMPuq8A4AACs4AAAxAAAAAAAAAAAAAACkgUJ7AQBw'
    'YXRjaGVzLzIwXzM1XzYwX05FV19HVUlERURfSU5UUk9fRklMRVMuZ2l0LnBhdGNoUEsFBgAAAAA+AD4AVxcAAIGKAQAAAA=='
    )
    [IO.File]::WriteAllBytes($PayloadZip, [Convert]::FromBase64String(($PayloadChunks -join '')))

    $Actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $PayloadZip).Hash.ToLowerInvariant()
    if ($Actual -ne $PayloadSha256) {
        throw 'Checksum do payload interno invalido.'
    }

    Expand-Archive -LiteralPath $PayloadZip -DestinationPath $PayloadDir -Force
    $Manifest = Get-Content (Join-Path $PayloadDir 'manifest.json') -Raw | ConvertFrom-Json

    foreach ($Entry in $Manifest.patches) {
        $PatchPath = Join-Path $PayloadDir ($Entry.file -replace '/', [IO.Path]::DirectorySeparatorChar)
        $sha = (Get-FileHash -Algorithm SHA256 -LiteralPath $PatchPath).Hash.ToLowerInvariant()
        if ($sha -ne $Entry.sha256) {
            throw "Checksum invalido: $($Entry.file)"
        }
    }

    Write-Host ("Branch: " + $CurrentBranch)
    Write-Host ("HEAD:   " + $StartHead)
    Write-Host ("Patches internos V2: " + $Manifest.patch_count)
    Write-Host ''

    Write-Host '[1/4] Criando worktree temporario...' -ForegroundColor Cyan
    Run-Git -Args @('worktree','add','--detach',$TempWorktree,$StartHead) -WorkingDirectory $RepoRoot

    Write-Host '[2/4] Preflight completo 01 -> 20...' -ForegroundColor Cyan
    $i = 0
    foreach ($Entry in $Manifest.patches) {
        $i++
        $PatchPath = Join-Path $PayloadDir ($Entry.file -replace '/', [IO.Path]::DirectorySeparatorChar)
        $Label = ("Task {0:D2} [{1}/{2}] - {3}" -f [int]$Entry.task, $i, [int]$Manifest.patch_count, [IO.Path]::GetFileName($Entry.file))
        Write-Host ('  ' + $Label) -NoNewline
        try {
            Apply-Patch -Repo $TempWorktree -Patch $PatchPath -Label $Label
            Write-Host '  OK' -ForegroundColor Green
        } catch {
            Write-Host '  FALHOU' -ForegroundColor Red
            throw "Preflight interrompido em $Label. O branch REAL nao foi alterado. $($_.Exception.Message)"
        }
    }

    foreach ($Relative in $Manifest.sentinels) {
        $TestPath = Join-Path $TempWorktree ($Relative -replace '/', [IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path $TestPath)) {
            throw "Arquivo esperado ausente no preflight: $Relative"
        }
    }

    Write-Host ''
    Write-Host '  PRE-FLIGHT 01-20 COMPLETO.' -ForegroundColor Green
    Write-Host ''

    Write-Host '[3/4] Criando backup...' -ForegroundColor Cyan
    Run-Git -Args @('branch',$BackupBranch,$StartHead) -WorkingDirectory $RepoRoot
    Write-Host ('  ' + $BackupBranch) -ForegroundColor Green

    Write-Host '[4/4] Aplicando no branch real...' -ForegroundColor Cyan
    try {
        $i = 0
        foreach ($Entry in $Manifest.patches) {
            $i++
            $PatchPath = Join-Path $PayloadDir ($Entry.file -replace '/', [IO.Path]::DirectorySeparatorChar)
            $Label = ("Task {0:D2} [{1}/{2}]" -f [int]$Entry.task, $i, [int]$Manifest.patch_count)
            Write-Host ('  ' + $Label) -NoNewline
            Apply-Patch -Repo $RepoRoot -Patch $PatchPath -Label $Label
            Write-Host '  OK' -ForegroundColor Green
        }
    } catch {
        Write-Host ''
        Write-Host 'Falha na aplicacao real; executando rollback...' -ForegroundColor Red
        Run-Git -Args @('reset','--hard',$StartHead) -WorkingDirectory $RepoRoot
        Run-Git -Args @('clean','-fd') -WorkingDirectory $RepoRoot
        throw "Rollback completo. $($_.Exception.Message)"
    }

    foreach ($Relative in $Manifest.sentinels) {
        $TestPath = Join-Path $RepoRoot ($Relative -replace '/', [IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path $TestPath)) {
            Run-Git -Args @('reset','--hard',$StartHead) -WorkingDirectory $RepoRoot
            Run-Git -Args @('clean','-fd') -WorkingDirectory $RepoRoot
            throw "Validacao final falhou em $Relative. Rollback executado."
        }
    }

    if ($Commit) {
        Run-Git -Args @('add','-A') -WorkingDirectory $RepoRoot
        Run-Git -Args @('commit','-m','feat: install mobile dungeon tasks 01-20 and guided intro') -WorkingDirectory $RepoRoot
    }

    Write-Host ''
    Write-Host '============================================================' -ForegroundColor Green
    Write-Host ' INSTALACAO V2 CONCLUIDA COM SUCESSO' -ForegroundColor Green
    Write-Host '============================================================' -ForegroundColor Green
    Write-Host ('Backup: ' + $BackupBranch)
    if (-not $Commit) {
        Write-Host 'Alteracoes aplicadas e NAO commitadas. Revise com: git status / git diff'
    }
}
catch {
    Write-Host ''
    Write-Host ('INSTALADOR INTERROMPIDO: ' + $_.Exception.Message) -ForegroundColor Red
    exit 1
}
finally {
    if (Test-Path $TempWorktree) {
        try { & git -C $RepoRoot worktree remove --force $TempWorktree 2>$null | Out-Null } catch {}
    }
    try { & git -C $RepoRoot worktree prune 2>$null | Out-Null } catch {}
    if (Test-Path $TempBase) {
        Remove-Item -Recurse -Force $TempBase -ErrorAction SilentlyContinue
    }
}
